import 'package:flutter_test/flutter_test.dart';import 'package:sai_college_mobile/models/roles.dart';
void main(){test('all nine roles are mapped',(){expect(AppRole.values.length,9);expect(RoleText.parse('content_editor'),AppRole.contentEditor);expect(RoleText.parse('super_admin'),AppRole.superAdmin);});test('multi role combines permissions',(){final result=allowedFeatures({AppRole.student,AppRole.teacher});expect(result.contains(Feature.attendance),isTrue);expect(result.contains(Feature.finance),isFalse);});test('parents do not get administrative modules',(){final result=allowedFeatures({AppRole.parent});expect(result.contains(Feature.users),isFalse);expect(result.contains(Feature.student),isTrue);});}
